    /// <summary>
    /// Find Wave table
    /// </summary>
    /// <param name = "_waveId">wave id</param>
    /// <param name = "_forUpdate">update buffer</param>
    /// <param name = "_concurrencyModel">concurrency model</param>
    /// <returns>METWaveTable</returns>
    static METWaveTable find(METWaveId         _waveId,
                             boolean          _forUpdate = false,
                             ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
    {
        METWaveTable  waveTable;

        if (_waveId)
        {
            if (_forUpdate)
            {
                waveTable.selectForUpdate (_forUpdate);
                if (_concurrencyModel != ConcurrencyModel::Auto)
                {
                    waveTable.concurrencyModel(_concurrencyModel);
                }
            }
            waveTable.selectLocked(_forUpdate);

            select firstonly waveTable
                where waveTable.WaveId == _waveId;
        }

        return waveTable;
    }

    /// <summary>
    /// Find Wave table by order extract date time
    /// </summary>
    /// <param name = "_orderExtractDateTime">Extract date time</param>
    /// <param name = "_forUpdate">update buffer true or false</param>
    /// <param name = "_concurrencyModel">Table locking</param>
    /// <returns>METWaveTable</returns>
    static METWaveTable findByOrderExtractDateTime(utcdatetime      _orderExtractDateTime,
                                                   boolean          _forUpdate = false,
                                                   ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
    {
        METWaveTable  waveTable;

        if (_orderExtractDateTime)
        {
            if (_forUpdate)
            {
                waveTable.selectForUpdate (_forUpdate);
                if (_concurrencyModel != ConcurrencyModel::Auto)
                {
                    waveTable.concurrencyModel(_concurrencyModel);
                }
            }
            waveTable.selectLocked(_forUpdate);

            select firstonly waveTable
                where waveTable.OrderExtractDateTime == _orderExtractDateTime;
        }

        return waveTable;
    }

    /// <summary>
    /// Checks if record exists
    /// </summary>
    /// <param name = "_waveId">wave Id</param>
    /// <returns>true or false</returns>
    static boolean exist(METWaveId  _waveId)
    {
        if (!_waveId)
        {
            return false;
        }

        return (select firstonly RecId from metWaveTable
                    index hint WaveIdx
                    where metWaveTable.WaveId == _waveId).RecId != 0;
    }

    /// <summary>
    /// Checks if order exists by order extract date time
    /// </summary>
    /// <param name = "_orderExtractDateTime">Order extract date time</param>
    /// <returns>true or false</returns>
    static boolean existByOrderExtractDateTime(utcdatetime  _orderExtractDateTime)
    {
        if (!_orderExtractDateTime)
        {
            return false;
        }

        return (select firstonly RecId from metWaveTable
                    index hint OrderExtractDateTimeIdx
                    where metWaveTable.OrderExtractDateTime == _orderExtractDateTime).RecId != 0;
    }

    /// <summary>
    /// Find the next unique Wave Id per CSDSalesId.
    /// </summary>
    /// <returns>Next unique unique Wave Id per CSDSalesId</returns>
    public static METWaveSeqNum nextWaveSeqNumSequence()
    {
        METWaveTable waveTable;

        select maxof(WaveSeqNum)
            from waveTable
            where waveTable.DataAreaId == curExt();
        
        return (waveTable.WaveSeqNum + 1);
    }

/// <summary>
/// Find the last wave sequence number
/// </summary>
/// <param name = "_waveId">wave Id</param>
/// <returns>Max unique LineCreationSequenceNumber</returns>
static METWaveSeqNum LastCustPickingSequenceNum(METWaveId _waveId)
{
    return (select maxof(WaveSeqNum) from metWaveTable
                index hint WaveIdx
                where  metWaveTable.WaveId == _waveId).WaveSeqNum;
}

    /// <summary>
    /// Table init value
    /// </summary>
    public void initValue()
    {
        super();

        this.WaveStatus = METCSDWaveStatus::Open;
        this.UserId = curUserId();
    }

    /// <summary>
    /// Generate wave Id
    /// </summary>
    /// <param name = "_orderExtractDateTime">Order extract date time</param>
    public void generateWaveId(utcdatetime _orderExtractDateTime)
    {
        //const str sequencePrefix = "W";
        int sequenceLength = 14;

        if (!METWaveTable::existByOrderExtractDateTime(_orderExtractDateTime))
        {
            int64 nextSequenceNumber = METWaveTable::nextWaveSeqNumSequence();

            // Ensure the next sequence number does not end in "100"
            while (nextSequenceNumber mod 100 == 0)
            {
                nextSequenceNumber++;
            }

            this.WaveSeqNum = nextSequenceNumber;
            str sequenceNumberStr = int642Str(nextSequenceNumber);

            // Calculate the number of zeros needed to pad the sequence number
            int zeroPadding = sequenceLength - strLen(sequenceNumberStr);

            // Construct the number sequence with the prefix and padded sequence number
            this.WaveId = "@MET:WaveIdSequencePrefix" + strRep('0', zeroPadding) + sequenceNumberStr;
            

        }
        else
        {
            // use the same wave Id if wave id found by order extract date time 
            METWaveTable waveTableLoc;

            select firstonly WaveSeqNum, WaveId from waveTableLoc 
                where waveTableLoc.OrderExtractDateTime == _orderExtractDateTime;

            if (waveTableLoc.WaveId && waveTableLoc.WaveSeqNum)
            {
                this.WaveId = waveTableLoc.WaveId;
                this.WaveSeqNum = waveTableLoc.WaveSeqNum;
            }

        }
    }

    /// <summary>
    /// Check if wave with wave num equal to zero exists for the warehouseid and the created date time
    /// </summary>
    /// <param name = "_inventLocationId">WarehouseId</param>
    /// <param name = "_createDateTime">CreatedDateTime</param>
    /// <returns>True or False</returns>
    static boolean existWaveNumWithZeroForInventLocationId(InventLocationId _inventLocationId, utcdatetime _createDateTime)
    {
        boolean ret = false;
        MetWaveTable waveTable;
        TransDate recordDate = DateTimeUtil::date(_createDateTime);
        utcdatetime minDateTime = DateTimeUtil::newDateTime(recordDate, 0);
        utcdatetime maxDateTime = DateTimeUtil::addSeconds(DateTimeUtil::addMinutes(DateTimeUtil::addHours(minDateTime, 23), 59), 59);
      
        select firstonly RecId from waveTable
            where waveTable.Warehouse == _inventLocationId
            && (waveTable.CreatedDateTime > minDateTime
            && waveTable.CreatedDateTime < maxDateTime)
            && waveTable.WaveNumber == 0;

       
        if (waveTable.RecId)
        {
            ret = true;
        }

        return ret;

    }

    /// <summary>
    /// Get wave num for wave
    /// </summary>
    /// <param name = "_inventLocationId">WarehouseId</param>
    /// <param name = "_createDateTime">CreatedDateTime</param>
    /// <returns>Wave Number</returns>
    static METWaveNumber getWaveNum(InventLocationId _inventLocationId, utcdatetime _createDateTime)
    {
        RefRecId        waveNumber;
        MetWaveTable    waveTable;

        TransDate recordDate = DateTimeUtil::date(_createDateTime);
        utcdatetime minDateTime = DateTimeUtil::newDateTime(recordDate, 0);
        utcdatetime maxDateTime = DateTimeUtil::addSeconds(DateTimeUtil::addMinutes(DateTimeUtil::addHours(minDateTime, 23), 59), 59);
      
        select maxof(WaveNumber) from waveTable            
            where waveTable.Warehouse == _inventLocationId
            && (waveTable.CreatedDateTime > minDateTime
            && waveTable.CreatedDateTime < maxDateTime)
            && waveTable.WaveNumber != 0;

        if (waveTable.WaveNumber > 0)
        {
            waveNumber = waveTable.WaveNumber + 1;
        }
        else if (waveTable.WaveNumber == 0)
        {
            waveNumber = waveTable.WaveNumber + 1;
        }

        return waveNumber;
    }

    /// <summary>
    /// Find record by extracted date time for the combination of ware house, site id
    /// </summary>
    /// <param name = "_inventLocationId">InventLocationId</param>
    /// <param name = "_orderExtractDateTime">ExtractedDatetime</param>
    /// <param name = "_forUpdate">update buffer</param>
    /// <param name = "_concurrencyModel">concurrency model</param>
    /// <returns>METWaveTable</returns>
    static METWaveTable findByWarehouseOrderExtractDateTime(InventLocationId     _inventLocationId,
                                                                utcdatetime      _orderExtractDateTime,
                                                                boolean          _forUpdate = false,
                                                                ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
    {
        METWaveTable  waveTable;

        if (_inventLocationId && _orderExtractDateTime)
        {
            if (_forUpdate)
            {
                waveTable.selectForUpdate (_forUpdate);
                if (_concurrencyModel != ConcurrencyModel::Auto)
                {
                    waveTable.concurrencyModel(_concurrencyModel);
                }
            }
            waveTable.selectLocked(_forUpdate);

            select firstonly waveTable
                index hint WarehouseOrderExtractDateTimeIdx
                where waveTable.Warehouse == _inventLocationId
                && waveTable.OrderExtractDateTime == _orderExtractDateTime;
        }

        return waveTable;
    }

    /// <summary>
    /// Check if record exists by extracteddatetime for the combination of ware house, site id
    /// </summary>
    /// <param name = "_inventLocationId">InventLocationId</param>
    /// <param name = "_orderExtractDateTime">ExtractedDatetime</param>
    /// <returns>True or false</returns>
    static boolean existByWarehouseOrderExtractDateTime(InventLocationId _inventLocationId,
                                                        utcdatetime      _orderExtractDateTime)
    {
        if (!_inventLocationId || DateTimeUtil::minValue() == _orderExtractDateTime)
        {
            return false;
        }

        return (select firstonly RecId from metWaveTable
                    index hint WarehouseOrderExtractDateTimeIdx
                    where metWaveTable.Warehouse == _inventLocationId
                    && metWaveTable.OrderExtractDateTime == _orderExtractDateTime).RecId != 0;
    }
